/* homesvc: show only main services and industries on the home page */(function(){var S=['product-ux-ui-design','frontend-development','website-design','brand-identity-design','website-development','mobile-app-design','web-app-development'],I=['defense-military-tech','edtech','saas','medtech-healthcare','gaming','ai-products','b2b-it-services','nonprofit-social-impact','health-wellness','web3-crypto'];function sel(p,a){return '.w-dyn-item'+a.map(function(s){return ':not(:has(a[href="/'+p+'/'+s+'"]))'}).join('')}var c=document.createElement('style');c.id='cc-homesvc';c.textContent='.section_home-services .w-tab-pane:nth-child(1) '+sel('services',S)+',.section_home-services .w-tab-pane:nth-child(2) '+sel('industries',I)+'{display:none!important}';document.head.appendChild(c);function fix(){var sec=document.querySelector('.section_home-services');if(!sec)return;var panes=sec.querySelectorAll('.w-tab-pane'),links=sec.querySelectorAll('.w-tab-link');panes.forEach(function(p,k){var n=0;p.querySelectorAll('.w-dyn-item').forEach(function(it){if(getComputedStyle(it).display==='none')return;n++;var w=document.createTreeWalker(it,4),t;while(t=w.nextNode()){if(/^\s*\d+\s*$/.test(t.nodeValue)&&t.parentElement.children.length===0){t.nodeValue=String(n);break}}});var cnt=links[k]&&links[k].querySelector('.navbar_works-number');if(cnt)cnt.textContent='('+n+')'})}if(document.readyState!=='loading')fix();else document.addEventListener('DOMContentLoaded',fix);window.addEventListener('load',function(){fix();setTimeout(fix,1000);setTimeout(fix,3000)})})();